import '@servicenow/sdk/global'
import { StringColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Flow, wfa, Subflow } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// Subflow definition to call
export const testSubflow = Subflow({
    $id: Now.ID['test_subflow_def'],
    name: 'Test Subflow',
    runAs: 'system',
    runWithRoles: [],
    flowPriority: 'LOW',
    inputs: {
        input1: StringColumn({ label: 'Input 1', mandatory: true }),
    },
    outputs: {
        output1: BooleanColumn({ label: 'Output 1', mandatory: true }),
    },
})

// Flow with subflow instances using runtime inputs
Flow(
    {
        $id: Now.ID['flow_runtime_inputs'],
        name: 'Flow - Subflow Runtime Inputs',
        description: 'Tests waitForCompletion runtime input',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_runtime_inputs'] },
        {
            table: 'task',
            condition: 'active=true',
            run_on_extended: 'false',
            run_flow_in: 'foreground',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_trigger) => {
        // Subflow with waitForCompletion only
        wfa.subflow(
            testSubflow,
            { $id: Now.ID['sub_wait_only'], annotation: 'sub_wait_only' },
            {
                input1: 'test1',
                waitForCompletion: true,
            }
        )

        // Subflow with defaults
        wfa.subflow(
            testSubflow,
            { $id: Now.ID['sub_defaults'], annotation: 'sub_defaults' },
            {
                input1: 'test4',
            }
        )
    }
)
